// wait out the wizard fight; eat nothing (no food); retreat if hp < 8 by walking away
const t0 = Date.now();
while (Date.now() - t0 < 35000) {
  const s = sdk.getState();
  if (!s.player.inCombat) break;
  if (s.player.hp < 8) { await bot.walkTo(3121, 3171, 2); break; }
  await sdk.waitForTicks(2);
}
await bot.dismissBlockingUI();
const s = sdk.getState();
const wizardAlive = (s.nearbyNpcs || []).some(n => /^wizard$/i.test(n.name || '') && n.inCombat && n.targetIndex === s.player.index);
